# chain over j (ssq, ymax): fused into 2 states (ssq, ymax.h0); derived: ymax.h0
#   ymax.h0 = max_j x[i, j]    (left when the contexts of ymax are taken out of its reduction)
def merge_j(a, b):
    return (
        (a[0] + b[0]),  # ssq
        tir.max(a[1], b[1]),  # ymax_h0
    )

def identity_j(t0, t1):
    return (tir.const(0.0, t0), tir.min_value(ty=t1))

fused_j = te.comm_reducer(merge_j, identity_j, name="fused_j")
j = te.reduce_axis((0, m), name="j")
ssq, ymax_h0 = te.compute(
    (n,),
    lambda i: fused_j(
        (
            (x[i, j] * x[i, j]),  # ssq
            x[i, j],  # ymax_h0
        ),
        axis=j,
    ),
    name="fused_ssq_ymax",
)
s = te.compute((n,), lambda i: (ssq[i] / m.astype("float32")), name="s")
ymax = te.compute((n,), lambda i: (ymax_h0[i] / (tir.sqrt((tir.const(1e-06, "float32") + (ssq[i] / m.astype("float32")))))), name="ymax")

