# chain over j (tot, ss): fused into 3 states (mean, ss, count); derived: count
#   count = Σ_j 1    (the extent of the axis, as far as it has been reduced)
def merge_j(a, b):
    t0 = (a[2] + b[2])
    t1 = (((a[0] * a[2]) + (b[0] * b[2])) / t0)
    return (
        t1,  # mean
        (a[1] + b[1] + (((t1 - a[0]) * (t1 - a[0])) * a[2]) + (((t1 - b[0]) * (t1 - b[0])) * b[2])),  # ss
        t0,  # count
    )

def identity_j(t0, t1, t2):
    return (tir.const(0.0, t0), tir.const(0.0, t1), tir.const(0.0, t2))

fused_j = te.comm_reducer(merge_j, identity_j, name="fused_j")
j = te.reduce_axis((0, m), name="j")
mean, ss, count = te.compute(
    (n,),
    lambda i: fused_j(
        (
            x[i, j],  # mean
            tir.const(0.0, "float32"),  # ss
            tir.const(1.0, "float32"),  # count
        ),
        axis=j,
    ),
    name="fused_tot_ss",
)

